performance.source:
[Module load: #time];
[[|
[System gc];
let started := [16 clockNanos];
[1 to: 500 do: [:i | [TaskExecutor current]]];
[System println: [[16 clockNanos] - started]];
[System println: [[TaskExecutor current] isNil]];
[System gc];
let started := [16 clockNanos];
[1 to: 500 do: [:i | [[TaskExecutor field: #quantum] set: i]]];
[System println: [[16 clockNanos] - started]];
[System println: [[[TaskExecutor field: #quantum] value] = 500]];
[[TaskExecutor field: #quantum] set: 128];
[System gc];
let facts := [db retainedFactCount];
let started := [16 clockNanos];
let task := [TaskControl start: [:self | 42]];
[1 to: 30 do: [:i | [TaskControl start: [:self | 42]]]];
[System println: [[16 clockNanos] - started]];
[System println: [[task pollOutcome] = #[#success 42]]];
[System println: [[db retainedFactCount] - facts]]
] value]
